<?php
declare(strict_types=1); require_once __DIR__ . '/../includes/auth.php'; require_auth(); require_once __DIR__ . '/../includes/csrf.php'; require_once __DIR__ . '/../config/database.php'; require_csrf();
$tracking=post_string('tracking',15);$receiver=(int)($_POST['receiver_id']??0);$remarks=post_string('remarks',500);$title=post_string('title',50);$userId=(int)$_SESSION['user_id'];$document=document_by_tracking($conn,$tracking);$route=current_route($conn,$tracking);
if(!$document||!$route||(int)$route['receiver']!==$userId||$document['status']!=='open'||$receiver<1||$remarks===''||strlen($title)<4){flash('error','Provide an active recipient, a 4+ character title, and forwarding remarks.');redirect('dashboard.php');}
if($receiver===$userId){flash('error','Choose another recipient.');redirect('documents/forward.php?tracking='.rawurlencode($tracking));}$check=$conn->prepare("SELECT id FROM dr_users WHERE id=? AND status <> 'Inactive' LIMIT 1");$check->bind_param('i',$receiver);$check->execute();if(!fetch_one($check)){flash('error','Choose an active recipient.');redirect('documents/forward.php?tracking='.rawurlencode($tracking));}
$conn->begin_transaction();try{$now=date('Y-m-d H:i:s');if($title!==$document['title']){$status='Change Title';$change=$document['title'].' --> '.$title;$log=$conn->prepare('INSERT INTO dr_logs (id_track,sender,receiver,status,date,remarks) VALUES (?,?,?,?,?,?)');$log->bind_param('siisss',$tracking,$userId,$receiver,$status,$now,$change);$log->execute();$edit=$conn->prepare('UPDATE dr_documents SET title=? WHERE id_track=?');$edit->bind_param('ss',$title,$tracking);$edit->execute();}$status='Pending';$log=$conn->prepare('INSERT INTO dr_logs (id_track,sender,receiver,status,date,remarks) VALUES (?,?,?,?,?,?)');$log->bind_param('siisss',$tracking,$userId,$receiver,$status,$now,$remarks);$log->execute();$conn->commit();flash('success','Document forwarded successfully.');redirect('documents/view.php?tracking='.rawurlencode($tracking));}catch(Throwable $error){$conn->rollback();error_log($error->getMessage());flash('error','Unable to forward the document.');redirect('documents/forward.php?tracking='.rawurlencode($tracking));}
